1	import 'dart:async';
2	import 'dart:io';
3	
4	import 'package:flutter/material.dart';
5	import 'package:flutter/semantics.dart';
6	import 'package:flutter_bloc/flutter_bloc.dart';
7	
8	import '../../../../core/design_tokens.dart';
9	import '../../../../core/widgets/app_button.dart';
10	import '../cubit/audio_entry_cubit.dart';
11	import '../cubit/photo_entry_cubit.dart';
12	import '../cubit/text_entry_cubit.dart';
13	
14	/// The Insertion Modal — a 3-tab bottom sheet (Texto/Áudio/Foto) opened
15	/// from the Home/Chat "+" control (`placeholder_screens.dart`). Texto,
16	/// Áudio and Foto are all functional as of spec-3-3 (Boundaries).
17	class InsertionModal extends StatelessWidget {
18	  const InsertionModal({
19	    required this.cubit,
20	    required this.audioCubit,
21	    required this.photoCubit,
22	    super.key,
23	  });
24	
25	  final TextEntryCubit cubit;
26	  final AudioEntryCubit audioCubit;
27	  final PhotoEntryCubit photoCubit;
28	
29	  /// Presents the modal exactly as the Boundaries dictate:
30	  /// `showModalBottomSheet(isScrollControlled: true, barrierColor:
31	  /// colorScrimHeavy)`, `radiusLg` top corners + `elevation2` (drawn by
32	  /// this widget's own `Container`, not Material's `elevation` double —
33	  /// same convention `ConfirmationDialog`'s card already uses), and a
34	  /// `durationSheetUp` entrance that collapses to zero under Reduce
35	  /// Motion (`MediaQuery.disableAnimations`).
36	  ///
37	  /// [cubit]/[audioCubit]/[photoCubit] are all fresh, `get_it`-factory-
38	  /// scoped instances — one trio per "+" tap (Boundaries: "Modal open
39	  /// resets") — closed here once the sheet is gone, regardless of how it
40	  /// closed (Salvar success, "x", swipe-down, or barrier dismiss) — the
41	  /// caller never has to remember to do this itself.
42	  static Future<void> show(
43	    BuildContext context, {
44	    required TextEntryCubit cubit,
45	    required AudioEntryCubit audioCubit,
46	    required PhotoEntryCubit photoCubit,
47	  }) async {
48	    final reduceMotion = MediaQuery.of(context).disableAnimations;
49	    final controller =
50	        BottomSheet.createAnimationController(Navigator.of(context))
51	          ..duration = reduceMotion
52	              ? Duration.zero
53	              : DesignTokens.durationSheetUp
54	          // Boundaries only names the entrance, but Reduce Motion should
55	          // collapse the exit the same way — otherwise dismissing the
56	          // sheet would still animate for anyone who asked for no motion.
57	          ..reverseDuration = reduceMotion ? Duration.zero : null;
58	    try {
59	      await showModalBottomSheet<void>(
60	        context: context,
61	        isScrollControlled: true,
62	        // Without this, the sheet's max-height constraint is the full
63	        // screen height including the status bar — with `isScrollControlled`
64	        // letting it grow to content height, a tall keyboard + content
65	        // combination pushed it up under the status bar/notch.
66	        useSafeArea: true,
67	        barrierColor: DesignTokens.colorScrimHeavy,
68	        backgroundColor: Colors.transparent,
69	        elevation: 0,
70	        transitionAnimationController: controller,
71	        builder: (_) => InsertionModal(
72	          cubit: cubit,
73	          audioCubit: audioCubit,
74	          photoCubit: photoCubit,
75	        ),
76	      );
77	      // Every dismissal path (Salvar success, "x", swipe-down, barrier tap)
78	      // routes back through this single `await` — the sheet's `TextField`
79	      // keeps system keyboard focus after `Navigator.pop()` unless it's
80	      // explicitly released here, otherwise the keyboard stays visible
81	      // over whatever screen is now underneath with no field in sight.
82	      FocusManager.instance.primaryFocus?.unfocus();
83	    } finally {
84	      // `showModalBottomSheet`'s own Future completes as soon as the
85	      // route is popped — *before* the exit (`reverse()`) animation the
86	      // framework drives on this same controller actually finishes.
87	      // Disposing immediately would cancel that animation's ticker
88	      // mid-flight, permanently freezing the sheet on screen (its
89	      // `AnimatedBuilder` keeps rendering the controller's last value,
90	      // and the route itself never reaches `AnimationStatus.dismissed`
91	      // to be removed from the `Overlay`). Documented behavior
92	      // (`BottomSheet.transitionAnimationController`'s own doc: "the
93	      // caller is responsible for disposing it when the controller is
94	      // no longer needed") — waiting for `dismissed` first is that
95	      // "no longer needed" point.
96	      if (!controller.isDismissed) {
97	        final animationDone = Completer<void>();
98	        void onStatusChange(AnimationStatus status) {
99	          if (status == AnimationStatus.dismissed) {
100	            animationDone.complete();
101	          }
102	        }
103	
104	        controller.addStatusListener(onStatusChange);
105	        await animationDone.future;
106	        controller.removeStatusListener(onStatusChange);
107	      }
108	      controller.dispose();
109	      // Review finding: each of the three cubits' cancel+close pair is
110	      // isolated in its own try/finally — without this, an exception
111	      // from an earlier step (e.g. `audioCubit.cancel()`) would skip
112	      // every later cleanup step entirely, leaking whichever cubit never
113	      // got to run its own `cancel()`/`close()`.
114	      try {
115	        await cubit.close();
116	      } finally {
117	        try {
118	          // Review finding: dismissing the whole modal while recording/
119	          // processing (the "x" button, swipe-down, or barrier tap — as
120	          // opposed to switching to another tab, which already went
121	          // through this same `cancel()`) never stopped the native
122	          // recording session; `close()` alone only cancels the
123	          // elapsed-seconds timer, not the recorder itself.
124	          // `discardPreserved: true` — unlike a tab switch, there's no
125	          // "switch back later" to preserve a transcribed/failed
126	          // recording for, so its temp file must be cleaned up here too
127	          // (Review finding) rather than leaking on disk forever once
128	          // `close()` below makes the cubit unreachable.
129	          await audioCubit.cancel(discardPreserved: true);
130	        } finally {
131	          try {
132	            await audioCubit.close();
133	          } finally {
134	            try {
135	              // Review finding: every `image_picker` pick writes a real
136	              // OS temp file — the comment this replaced incorrectly
137	              // claimed Foto "never creates a temp file of its own".
138	              // Same `discardPreserved: true` rationale as Áudio's own
139	              // call above: there's no "switch back later" once the
140	              // whole modal is closing, so a preserved
141	              // `PhotoRecognized`/`PhotoError`'s picked file must be
142	              // cleaned up here too rather than leaking on disk forever.
143	              await photoCubit.cancel(discardPreserved: true);
144	            } finally {
145	              await photoCubit.close();
146	            }
147	          }
148	        }
149	      }
150	    }
151	  }
152	
153	  @override
154	  Widget build(BuildContext context) {
155	    return MultiBlocProvider(
156	      providers: [
157	        BlocProvider.value(value: cubit),
158	        BlocProvider.value(value: audioCubit),
159	        BlocProvider.value(value: photoCubit),
160	      ],
161	      child: const _InsertionModalBody(),
162	    );
163	  }
164	}
165	
166	/// Coarse `AudioCaptureState` discriminator used only to decide whether a
167	/// given emission is a genuine transition worth announcing — e.g.
168	/// [AudioRecording]'s own per-second timer tick re-emits the same kind
169	/// repeatedly and must never re-announce "Gravando áudio" every second.
170	enum _AudioAnnounceKind {
171	  idle,
172	  recording,
173	  processing,
174	  transcribed,
175	  saving,
176	  saved,
177	  error,
178	}
179	
180	_AudioAnnounceKind _audioAnnounceKindOf(AudioCaptureState state) =>
181	    switch (state) {
182	      AudioIdle() => _AudioAnnounceKind.idle,
183	      AudioRecording() => _AudioAnnounceKind.recording,
184	      AudioProcessing() => _AudioAnnounceKind.processing,
185	      AudioTranscribed(saving: true) => _AudioAnnounceKind.saving,
186	      AudioTranscribed() => _AudioAnnounceKind.transcribed,
187	      AudioSaved() => _AudioAnnounceKind.saved,
188	      AudioError() => _AudioAnnounceKind.error,
189	    };
190	
191	/// Same "only announce a genuine transition" role as [_AudioAnnounceKind],
192	/// for `PhotoEntryCubit`.
193	enum _PhotoAnnounceKind { idle, processing, recognized, saving, saved, error }
194	
195	_PhotoAnnounceKind _photoAnnounceKindOf(PhotoCaptureState state) =>
196	    switch (state) {
197	      PhotoIdle() => _PhotoAnnounceKind.idle,
198	      PhotoProcessing() => _PhotoAnnounceKind.processing,
199	      PhotoRecognized(saving: true) => _PhotoAnnounceKind.saving,
200	      PhotoRecognized() => _PhotoAnnounceKind.recognized,
201	      PhotoSaved() => _PhotoAnnounceKind.saved,
202	      PhotoError() => _PhotoAnnounceKind.error,
203	    };
204	
205	class _InsertionModalBody extends StatefulWidget {
206	  const _InsertionModalBody();
207	
208	  @override
209	  State<_InsertionModalBody> createState() => _InsertionModalBodyState();
210	}
211	
212	class _InsertionModalBodyState extends State<_InsertionModalBody> {
213	  final _textController = TextEditingController();
214	
215	  /// The Áudio tab's own text field controller — lifted up here rather
216	  /// than owned by `_AudioTab` itself so it survives `_AudioTab` being
217	  /// rebuilt on every `AudioCaptureState` change without losing cursor
218	  /// position/focus, same rationale as [_textController] living here
219	  /// instead of inside `_TextoTab`.
220	  final _audioTextController = TextEditingController();
221	
222	  /// The Foto tab's own text field controller — same "lifted up" rationale
223	  /// as [_audioTextController].
224	  final _photoTextController = TextEditingController();
225	
226	  /// The last `AudioTranscribed.path` this controller's text was synced
227	  /// from — only a *new* transcription (a different/first path) resets
228	  /// the controller's text; the user's own edits via `onChanged` never
229	  /// get clobbered by an unrelated rebuild.
230	  String? _lastSyncedAudioPath;
231	
232	  /// Same role as [_lastSyncedAudioPath], for `PhotoRecognized.path` — a
233	  /// *new* `PhotoRecognized` for a path not yet synced (the initial OCR
234	  /// success, or a retried OCR landing after an error that never
235	  /// synced) overwrites the controller; the user's own edits (which
236	  /// re-emit the same path) never do.
237	  String? _lastSyncedPhotoPath;
238	
239	  /// Tracks the previously-seen `activeTab` so the listener can tell a
240	  /// genuine tab switch apart from the many other `TextEntryIdle`
241	  /// emissions a keystroke produces (`updateText` also emits `Idle`) —
242	  /// initialized from the cubit's own current state so the very first
243	  /// comparison (before any emission the listener sees) is still correct.
244	  late CaptureTab _lastAnnouncedTab;
245	
246	  /// Same "only announce a genuine transition" guard as [_lastAnnouncedTab],
247	  /// for `AudioEntryCubit` (see [_audioAnnounceKindOf]).
248	  late _AudioAnnounceKind _lastAudioAnnouncedKind;
249	
250	  /// Same role as [_lastAudioAnnouncedKind], for `PhotoEntryCubit` (see
251	  /// [_photoAnnounceKindOf]).
252	  late _PhotoAnnounceKind _lastPhotoAnnouncedKind;
253	
254	  @override
255	  void initState() {
256	    super.initState();
257	    _lastAnnouncedTab = context.read<TextEntryCubit>().state.activeTab;
258	    _lastAudioAnnouncedKind = _audioAnnounceKindOf(
259	      context.read<AudioEntryCubit>().state,
260	    );
261	    _lastPhotoAnnouncedKind = _photoAnnounceKindOf(
262	      context.read<PhotoEntryCubit>().state,
263	    );
264	  }
265	
266	  @override
267	  void dispose() {
268	    _textController.dispose();
269	    _audioTextController.dispose();
270	    _photoTextController.dispose();
271	    super.dispose();
272	  }
273	
274	  // Labels for the 3 tabs, shared between the announcement below and
275	  // `_TabBar`'s own rendering (`_TabBar._tabs`) — kept here too since
276	  // `selectTab`'s announcement needs the label for whichever tab the
277	  // user just switched *to*, not the cubit's own (enum-only) state.
278	  static const _tabLabels = {
279	    CaptureTab.texto: 'Texto',
280	    CaptureTab.audio: 'Áudio',
281	    CaptureTab.foto: 'Foto',
282	  };
283	
284	  // Mirrors `account_settings_screen.dart`'s own `_announce` — VoiceOver
285	  // (this app is iOS-only) doesn't reliably treat a live-region subtree
286	  // update as an announcement on its own, so every state change this
287	  // story introduces — saving, success, failure, and a tab switch — is
288	  // spoken explicitly here instead (Acceptance Criteria: "no
289	  // color/animation alone").
290	  Future<void> _announce(String message) async {
291	    if (!mounted) {
292	      return;
293	    }
294	    await SemanticsService.sendAnnouncement(
295	      View.of(context),
296	      message,
297	      TextDirection.ltr,
298	    );
299	  }
300	
301	  void _onTextEntryStateChange(BuildContext context, TextEntryState state) {
302	    // Review finding: a tab switch (re-emitted as `TextEntryIdle`,
303	    // same as every keystroke) previously went unannounced —
304	    // detected here by comparing against the last tab seen, so a
305	    // plain keystroke (same `activeTab`) never re-triggers it.
306	    if (state.activeTab != _lastAnnouncedTab) {
307	      final previousTab = _lastAnnouncedTab;
308	      _lastAnnouncedTab = state.activeTab;
309	      _announce('Aba ${_tabLabels[state.activeTab]} selecionada');
310	      // spec-3-2's Code Map: tab-switch detection also drives
311	      // `AudioEntryCubit.startRecording()`/`.cancel()` — entering Áudio
312	      // starts recording immediately (Acceptance Criteria), leaving it
313	      // stops/releases the recorder (I/O matrix: "Leave tab
314	      // mid-recording"), never the full Story 3.4 cancel choreography.
315	      final audioCubit = context.read<AudioEntryCubit>();
316	      if (state.activeTab == CaptureTab.audio) {
317	        unawaited(audioCubit.startRecording());
318	      } else if (previousTab == CaptureTab.audio) {
319	        unawaited(audioCubit.cancel());
320	      }
321	      // spec-3-3's Code Map: leaving Foto mid-pick/mid-OCR discards the
322	      // in-flight picker/OCR call (I/O matrix: "Leave tab mid-pick/OCR")
323	      // — unlike Áudio, entering Foto never starts anything on its own
324	      // (picking only ever starts from an explicit Câmera/Galeria tap).
325	      if (previousTab == CaptureTab.foto) {
326	        unawaited(context.read<PhotoEntryCubit>().cancel());
327	      }
328	    }
329	    switch (state) {
330	      case TextEntrySaved():
331	        // I/O matrix: "success closes the modal". Review finding:
332	        // wait for the announcement to actually be sent before
333	        // popping — previously fired-and-forgot in the same tick,
334	        // risking the announcement being cut off by the dismiss
335	        // transition.
336	        unawaited(
337	          _announce('Registro salvo').then((_) {
338	            if (context.mounted) {
339	              Navigator.of(context).pop();
340	            }
341	          }),
342	        );
343	      case TextEntrySaving():
344	        _announce('Salvando registro');
345	      case TextEntryError():
346	        _announce(state.message);
347	      case TextEntryIdle():
348	        break;
349	    }
350	  }
351	
352	  void _onAudioStateChange(BuildContext context, AudioCaptureState state) {
353	    if (state is AudioTranscribed && state.path != _lastSyncedAudioPath) {
354	      _lastSyncedAudioPath = state.path;
355	      _audioTextController.text = state.text;
356	    }
357	    final kind = _audioAnnounceKindOf(state);
358	    if (kind == _lastAudioAnnouncedKind) {
359	      return;
360	    }
361	    _lastAudioAnnouncedKind = kind;
362	    switch (state) {
363	      case AudioRecording():
364	        _announce('Gravando áudio');
365	      case AudioProcessing():
366	        _announce('Transcrevendo áudio');
367	      case AudioTranscribed(saving: true):
368	        _announce('Salvando registro');
369	      case AudioTranscribed():
370	        _announce('Transcrição concluída. Revise o texto antes de salvar.');
371	      case AudioError(message: final message):
372	        _announce(message);
373	      case AudioSaved():
374	        // Same "wait for the announcement" rationale as
375	        // `TextEntrySaved` above.
376	        unawaited(
377	          _announce('Registro salvo').then((_) {
378	            if (context.mounted) {
379	              Navigator.of(context).pop();
380	            }
381	          }),
382	        );
383	      case AudioIdle():
384	        // Review finding: the one `AudioCaptureState` transition
385	        // previously never announced — reachable today only via
386	        // `cancel()` resetting from `AudioRecording` (a tab switch away
387	        // mid-recording), which happened to already be covered by the
388	        // separate tab-switch announcement above, masking the gap.
389	        _announce('Gravação cancelada');
390	    }
391	  }
