393	  void _onPhotoStateChange(BuildContext context, PhotoCaptureState state) {
394	    if (state is PhotoRecognized && state.path != _lastSyncedPhotoPath) {
395	      _lastSyncedPhotoPath = state.path;
396	      _photoTextController.text = state.text;
397	    }
398	    final kind = _photoAnnounceKindOf(state);
399	    if (kind == _lastPhotoAnnouncedKind) {
400	      return;
401	    }
402	    _lastPhotoAnnouncedKind = kind;
403	    switch (state) {
404	      case PhotoProcessing():
405	        _announce('Reconhecendo texto da foto');
406	      case PhotoRecognized(saving: true):
407	        _announce('Salvando registro');
408	      case PhotoRecognized():
409	        _announce('Texto reconhecido. Revise o texto antes de salvar.');
410	      case PhotoError(message: final message):
411	        _announce(message);
412	      case PhotoSaved():
413	        // Same "wait for the announcement" rationale as
414	        // `TextEntrySaved`/`AudioSaved` above.
415	        unawaited(
416	          _announce('Registro salvo').then((_) {
417	            if (context.mounted) {
418	              Navigator.of(context).pop();
419	            }
420	          }),
421	        );
422	      case PhotoIdle():
423	        // Reachable via `cancel()` resetting from `PhotoProcessing` (a
424	        // tab switch away mid-pick/mid-OCR), same rationale as
425	        // `AudioIdle`'s own "Gravação cancelada" above.
