1080	class _WaveformState extends State<_Waveform> {
1081	  // `growable: true` — `build()` below reads this with `removeAt`/`add`
1082	  // on every new amplitude sample, which `List.filled`'s own default
1083	  // fixed-length list doesn't support.
1084	  final List<double> _samples = List.filled(
1085	    _waveformBarCount,
1086	    0.1,
1087	    growable: true,
1088	  );
1089	  StreamSubscription<double>? _subscription;
