1091	  @override
1092	  void initState() {
1093	    super.initState();
1094	    _subscription = widget.amplitudeStream?.listen(
1095	      (amplitude) {
1096	        if (!mounted) {
1097	          return;
1098	        }
1099	        setState(() {
1100	          _samples.removeAt(0);
1101	          // `num.clamp` returns `num`, not `double` — `_samples` is
1102	          // `List<double>`.
1103	          _samples.add(amplitude.clamp(0.1, 1.0).toDouble());
1104	        });
1105	      },
1106	      // Review finding: an unhandled `onError` turns a native amplitude-
1107	      // stream error into an uncaught async exception — the waveform
1108	      // just stays frozen on its last sample instead, no worse than the
1109	      // already-handled "no live stream" (frozen/processing) case.
1110	      onError: (_) {},
1111	    );
1112	  }
1113	
1114	  @override
1115	  void dispose() {
1116	    _subscription?.cancel();
1117	    super.dispose();
1118	  }
